export const mockGridViewModel = (appointmentData, partialViewModel) => {
    const sourceAppointment = {
        allDay: appointmentData.allDay,
        startDate: appointmentData.startDate,
        endDate: appointmentData.endDate
    };
    const viewModel = {
        itemData: appointmentData,
        allDay: appointmentData.allDay ?? false,
        groupIndex: appointmentData.groupIndex ?? 0,
        sortedIndex: appointmentData.sortedIndex ?? 0,
        info: {
            sourceAppointment: sourceAppointment,
            appointment: Object.assign({}, sourceAppointment)
        },
        direction: "horizontal",
        skipResizing: false,
        level: 0,
        maxLevel: 0,
        empty: false,
        left: 0,
        top: 0,
        height: 0,
        width: 0,
        reduced: void 0,
        partIndex: 0,
        partTotalCount: 0,
        rowIndex: 0,
        columnIndex: 0
    };
    return Object.assign({}, viewModel, partialViewModel)
};
